 "model": {
  "variables": [
   {
    "name": "escalators",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "elevators",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "escalators",
     "coef": 2400.0
    },
    {
     "var": "elevators",
     "coef": 1000.0
    }
   ]
  },
  "constraints": [
   {
    "name": "total_transportation_methods",
    "terms": [
     {
      "var": "escalators",
      "coef": 1.0
     },
     {
      "var": "elevators",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 100.0
   },
   {
    "name": "more_escalators_than_elevators",
    "terms": [
